"""Технический отчёт о разборе архива. Показывает разбиение по источникам, а не выводы о здоровье."""
import html

def table(headers,rows):
 return '<table><tr>'+''.join('<th>'+html.escape(str(v))+'</th>' for v in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</table>'

HEAD='''<!doctype html><meta charset="utf-8"><title>Локальный предварительный отчёт</title><style>body{font:16px system-ui;max-width:1200px;margin:40px auto;padding:20px}table{border-collapse:collapse;font-size:13px}td,th{border:1px solid #ccc;padding:6px}th{background:#eee}p{line-height:1.5}</style><h1>Apple Health: локальная инвентаризация</h1><p>Источники показаны раздельно; суммировать их нельзя. Отсутствие записей не означает нулевую активность. Доля дней с данными не измеряет время ношения часов.</p><p>Суммы с перекрытиями предварительные: без приоритета источников Health их нельзя считать эквивалентом приложения. Сон — объединение интервалов сна внутри источника, по календарным дням, а не ночам. Средние пульса, VO₂max и сна — средние наблюдаемых дневных значений. Редкие измерения VO₂max нормальны; знаменатель календарных дней не является оценкой качества.</p><p>Источники разделены по приложению, версии и описанию устройства. Служебный адрес объекта HKDevice исключён из ключа источника; остальные поля сохранены. Без устойчивого идентификатора одинаковые описания устройств могут быть неразличимы. Смена ID может быть обновлением, а не покупкой часов. Названия владельца и идентификаторы устройства не сохранены. Часовой пояс берётся из записи; пересечение полуночи распределяется пропорционально времени. Интервалы со сменой UTC-смещения требуют дополнительной проверки.</p><h2>Проверка со «Здоровьем»</h2><p>Выберите полный недавний месяц и один старый месяц: сравните шаги, минуты упражнений, тренировки, пульс покоя, VO₂max и несколько ночей сна. Зафиксируйте период, показатель, итог приложения и используемые источники. До сверки не интерпретируйте различия как изменения здоровья.</p>'''

def report_html(counters,sources,yearly,gaps,monthly):
 report=HEAD
 report+='<h2>Качество обработки</h2>'+table(['check','count'],counters.items())
 report+='<h2>Источники</h2>'+table(['ID','категория / версия'],sources)
 report+='<h2>Доступность по годам</h2>'+table(['показатель','источник','год','дней','первая дата','последняя дата'],yearly)
 report+='<h2>Пробелы ≥ 30 дней между наблюдениями</h2>'+table(['показатель','источник','до','после','дней'],[r for r in gaps if r[-1]>=30])
 report+='<h2>Месячные сводки</h2><p>Полностью пустые месяцы отсутствуют в таблице, а не заполнены нулями. Для продолжительности тренировок используются заявленные минуты (паузы не прибавляются); распределение через полночь приблизительное. Строки workout_*_count считают начала тренировок. Стадии сна отдельно не сравниваются: их доступность зависит от поколения алгоритма.</p>'+table(['показатель','источник','месяц','значение','расчёт','дней','дней месяца','доля','записей/частей','дней перекрытий'],monthly)
 return report
